#include "mtie/transformer.hpp"
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
int main(){try{auto p=mtie::stable_softmax({1000,1001});if(std::abs(p[0]+p[1]-1)>1e-6||!std::isfinite(p[0]))throw std::runtime_error("softmax");std::vector<float>x={1,3};mtie::layer_norm(x,{1,1},{0,0});if(std::abs(x[0]+x[1])>1e-5)throw std::runtime_error("norm");auto w=mtie::make_deterministic_demo();auto file=std::filesystem::temp_directory_path()/"mtie_test_weights.mtie";mtie::save_weights(w,file);auto restored=mtie::load_weights(file);if(restored.parameter_count()!=w.parameter_count())throw std::runtime_error("weight round trip");std::ofstream bad(file,std::ios::binary|std::ios::trunc);bad<<"not weights";bad.close();bool rejected=false;try{(void)mtie::load_weights(file);}catch(const std::runtime_error&){rejected=true;}std::filesystem::remove(file);if(!rejected)throw std::runtime_error("invalid weights accepted");mtie::Transformer m(w);auto a=m.logits({2,3});auto b=m.logits({2,3,4});if(a.size()!=w.config.vocab_size||b.size()!=w.config.vocab_size)throw std::runtime_error("shape");auto r1=m.generate({2},5,.8f,4,99),r2=m.generate({2},5,.8f,4,99);if(r1!=r2)throw std::runtime_error("seed repeatability");/* Causal attention only enumerates keys 0..t, so a later suffix cannot alter a prefix run. */if(m.logits({2,3})!=a)throw std::runtime_error("causal prefix");std::cout<<"all tests passed\n";}catch(const std::exception&e){std::cerr<<"test failed: "<<e.what()<<'\n';return 1;}}
